 239   public addChapter(title: string = "Untitled Chapter"): Project {
 240     const newChapter = new Chapter({ title, sections: [] });
 241     return this.with({ content: [...this.content, newChapter] });
 242   }
 243 
 244   public addSectionToChapter(chapterId: string, sectionTitle: string, content?: string): Project {
 245     return this.updateChapter(chapterId, (chapter) =>
 246         chapter.addSection(new Section({ title: sectionTitle, type: 'report', content }))
 247     );
 248   }
 249 
 250   public updateChapter(id: string, updater: (c: Chapter) => Chapter): Project {
 251     const idx = this.content.findIndex(c => c.id === id && c instanceof Chapter);
 252     if (idx === -1) return this;
 253 
 254     const newContent = [...this.content];
 255     const originalChapter = newContent[idx] as Chapter;
 256     newContent[idx] = updater(originalChapter);
 257 
 258     return this.with({ content: newContent });
 259   }
 260 
 261   public removeChapter(id: string): Project {
 262     return this.with({ content: this.content.filter(c => c.id !== id) });
 263   }
 264 
 265   public updateSection(id: string, updater: (s: Section) => Section): Project {
 266     let sectionFound = false;
 267     const newContent = this.content.map(item => {
 268       if (item instanceof Section && item.id === id) {
 269         sectionFound = true;
 270         return updater(item);
 271       }
 272       if (item instanceof Chapter) {
 273         const originalSections = item.sections;
 274         const updatedSections = item.sections.map(s => {
 275           if (s.id === id) {
 276             sectionFound = true;
 277             return updater(s);
 278           }
 279           return s;
 280         });
 281         if (originalSections !== updatedSections) {
 282           return item.with({ sections: updatedSections });
 283         }
 284       }
 285       return item;
 286     });
 287 
 288     return sectionFound ? this.with({ content: newContent }) : this;
 289   }
