 315   public parseAndSetContentFromToc(tocText: string): ProjectContent {
 316     const lines = tocText.split('\n').filter(line => line.trim() !== '');
 317     const newContent: Chapter[] = [];
 318     let currentChapter: Chapter | null = null;
 319 
 320     lines.forEach(line => {
 321         const isSection = line.trim().match(/^\s*-\s/) || line.trim().match(/^\d+\.\d+/);
 322         const isChapter = line.trim().startsWith('# ') || line.trim().match(/^\d+\./);
 323 
 324         if (isChapter && !isSection) {
 325             if (currentChapter) {
 326                 newContent.push(currentChapter);
 327             }
 328             const title = line.replace(/^#\s*/, '').replace(/^\d+\.\s*/, '').trim();
 329             currentChapter = new Chapter({ title, sections: [] });
 330         } else if (currentChapter) {
 331             const title = line.replace(/^\s*-\s*/, '').replace(/^\d+\.\d+\.?\s*/, '').trim();
 332             if (title) {
 333                 const newSection = new Section({ title, type: 'report' });
 334                 currentChapter = currentChapter.addSection(newSection);
 335             }
 336         }
 337     });
 338 
 339     if (currentChapter) {
 340         newContent.push(currentChapter);
 341     }
 342 
